 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Complete a missing horizontal stripe by wrapping the stripe sequence.
    row_colors = []
    stripe_grid = True
    for row in grid:
        vals = set(row)
        if len(vals) != 1:
            stripe_grid = False
            break
        row_colors.append(next(iter(vals)))
    if stripe_grid:
        nonzero_rows = [r for r, color in enumerate(row_colors) if color != 0]
        for r, color in enumerate(row_colors):
            if color == 0 and nonzero_rows:
                source = nonzero_rows[-1] if r == 0 else nonzero_rows[0]
                out[r] = [row_colors[source]] * w
        return out

    # The colored diagonal tracks are parallel, so their c-r offsets encode
    # one period of a diagonal repeating pattern. Find the shortest period
    # that assigns no offset class two different colors.
    offset_colors = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                d = c - r
                if d in offset_colors and offset_colors[d] != color:
                    # Not a single diagonal-track motif; leave untouched.
                    return out
                offset_colors[d] = color
    if not offset_colors:
        return out

    max_period = max(h, w) * 2
    period = None
    for p in range(1, max_period + 1):
        classes = {}
        valid = True
        for d, color in offset_colors.items():
            phase = d % p
            if phase in classes and classes[phase] != color:
                valid = False
                break
            classes[phase] = color
        if valid:
            period = p
            pattern = classes
            break
    if period is None:
        return out

    for r in range(h):
        for c in range(w):
            phase = (c - r) % period
            if phase in pattern:
                out[r][c] = pattern[phase]
    return out


